		/** 
		 * Tests creating a new Coupon.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Coupon");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Coupon" );

			try {            
				Coupon entity = CouponService.getCouponInstance().createCoupon( generateNewEntity() );
				thePrimaryKey = entity.getCouponId();
				LOGGER.info( "-- Successfully created a Coupon with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Coupon. 
		 */
		public Coupon testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Coupon" );

			Coupon entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Coupon with primary key" );
			msg.append( thePrimaryKey );
			
			CouponFetchOneSummary fetchOneSummary = new CouponFetchOneSummary( thePrimaryKey );

			try {
				entity = CouponService.getCouponInstance().getCoupon( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Coupon " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Coupon.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Coupon." );

			StringBuilder msg = new StringBuilder( "Failed to update a Coupon : " );        
			Coupon entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Coupon." );

				// for use later on...
				thePrimaryKey = entity.getCouponId();

				CouponService proxy = CouponService.getCouponInstance();            
				proxy.updateCoupon( entity );   

				LOGGER.info( "-- Successfully saved Coupon - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Coupon.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Coupon." );

			try{
			    Coupon entity = testRead(); 
				CouponService.getCouponInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Coupon with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Coupon with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Coupons.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Coupons:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Coupon : " );        
			List<Coupon> collection  = null;

			try {
				// call the static get method on the CouponService
				collection = CouponService.getCouponInstance().getAllCoupon();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Coupon entity = null;            
					Iterator<Coupon> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getCouponId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

